package fraymus.workspace;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
public class Load056RecoveryTest {
 @Test public void actualInterruptedLoadRetainsOriginalsAndRejectsTampering()throws Exception{Path root=Files.createTempDirectory("load056-recovery-");var worlds=new WorldLedger(root);var in=Load056Test.input(worlds,"wide",.8,0);var before=worlds.observe(in.getString("worldId"));var source=worlds.source(before);var plan=Design056.proposals(source,worlds.preview(in)).getJSONObject(1).getJSONObject("plan");var run=Construction054Test.nativeRun(root.resolve("assembly"),source,plan);Path loads=root.resolve("loads"),file=loads.resolve(run.getString("id")+".json");var calls=new AtomicInteger();assertThrows(InterruptedException.class,()->Load056.evaluate(loads,run,16,()->calls.incrementAndGet()>=10));var stopped=AgentFiles042.read(file,64_000_000).getJSONObject("data");assertEquals("completed",stopped.getJSONArray("attempts").getJSONObject(0).getString("status"));assertEquals("interrupted",stopped.getJSONArray("attempts").getJSONObject(1).getString("status"));assertTrue(stopped.getJSONArray("attempts").getJSONObject(1).getJSONArray("rows").length()>0);Files.writeString(root.resolve("original-stopped.json"),Load056.original(loads,run,16).toString());String first=stopped.getJSONArray("attempts").getJSONObject(0).toString();var result=Load056.evaluate(loads,run,16,()->false);assertTrue(result.getBoolean("qualifies"));var restored=AgentFiles042.read(file,64_000_000).getJSONObject("data");assertTrue(new JSONObject(first).similar(restored.getJSONArray("attempts").getJSONObject(0)));assertEquals(12,result.getInt("attempts"));assertTrue(result.getInt("totalTicks")>15840);Files.writeString(root.resolve("original-resumed.json"),Load056.original(loads,run,16).toString());byte[] original=Files.readAllBytes(file);
  for(String change:List.of("force","point","missing","source")){var d=AgentFiles042.read(file,64_000_000).getJSONObject("data");var a=d.getJSONArray("attempts").getJSONObject(0);switch(change){case"force"->a.getJSONArray("rows").getJSONArray(0).getJSONArray(1).put(1,-1);case"point"->a.getJSONArray("rows").getJSONArray(0).getJSONArray(4).put(0,0);case"missing"->a.getJSONArray("rows").remove(2);case"source"->d.put("sourceRunSha256","0".repeat(64));}AgentFiles042.saveChecked(file,d);assertThrows(change,IllegalStateException.class,()->Load056.read(loads,run,16));Files.write(file,original);}assertTrue(before.similar(worlds.observe(in.getString("worldId"))));Files.writeString(root.resolve("result.json"),result.toString());System.out.println("LOAD056_RECOVERY "+root);
 }
}
